import { useState, useEffect } from 'react';
import { Card, Table, Button, Input, Modal, Form, DatePicker, Select, message, Space, Tag, Checkbox } from 'antd';
import { PlusOutlined, SearchOutlined, EditOutlined, DeleteOutlined, EyeOutlined, PrinterOutlined } from '@ant-design/icons';
import { fetchPatients, createPatient, updatePatient, deletePatient } from '../lib/api';
import { PrintQueueTicketButton } from '../components/PrintQueueTicketButton';
import dayjs from 'dayjs';

const { Search } = Input;

export function ReceptionPage() {
  const [waitingPatients, setWaitingPatients] = useState([]);
  const [inProgressPatients, setInProgressPatients] = useState([]);
  const [completedPatients, setCompletedPatients] = useState([]);
  const [loading, setLoading] = useState(false);
  const [modalVisible, setModalVisible] = useState(false);
  const [detailsVisible, setDetailsVisible] = useState(false);
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [form] = Form.useForm();

  useEffect(() => {
    loadPatients();
    const interval = setInterval(loadPatients, 30000); // Refresh every 30s
    return () => clearInterval(interval);
  }, []);

  const loadPatients = async (q = '') => {
    try {
      setLoading(true);
      const data = await fetchPatients(q);

      // Filter by visitStatus
      setWaitingPatients(data.filter(p => p.visitStatus === 'waiting'));
      setInProgressPatients(data.filter(p => p.visitStatus === 'in_progress'));
      setCompletedPatients(data.filter(p => p.visitStatus === 'completed'));
    } catch (error) {
      message.error('Không thể tải danh sách bệnh nhân');
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (value) => {
    setSearchQuery(value);
    loadPatients(value);
  };

  const handleAdd = () => {
    setSelectedPatient(null);
    form.resetFields();
    setModalVisible(true);
  };

  const handleEdit = (record) => {
    setSelectedPatient(record);
    // Convert visitPurpose string to array for checkbox
    let visitPurposeValue = record.visitPurpose;
    if (visitPurposeValue && visitPurposeValue.includes(',')) {
      visitPurposeValue = visitPurposeValue.split(',');
    } else if (visitPurposeValue === 'both') {
      visitPurposeValue = ['examination', 'refraction'];
    } else {
      visitPurposeValue = [visitPurposeValue];
    }

    form.setFieldsValue({
      ...record,
      birthDate: record.birthDate ? dayjs(record.birthDate) : null,
      visitPurpose: visitPurposeValue
    });
    setModalVisible(true);
  };

  const handleViewDetails = (record) => {
    setSelectedPatient(record);
    setDetailsVisible(true);
  };

  const handleDelete = async (id) => {
    Modal.confirm({
      title: 'Xác nhận xóa',
      content: 'Bạn có chắc chắn muốn xóa bệnh nhân này?',
      okText: 'Xóa',
      cancelText: 'Hủy',
      okButtonProps: { danger: true },
      onOk: async () => {
        try {
          await deletePatient(id);
          message.success('Đã xóa bệnh nhân');
          loadPatients(searchQuery);
        } catch (error) {
          message.error('Không thể xóa bệnh nhân');
        }
      }
    });
  };

  const handleSubmit = async (values) => {
    try {
      // Convert visitPurpose array to string
      let visitPurpose = 'both';
      if (values.visitPurpose && Array.isArray(values.visitPurpose)) {
        if (values.visitPurpose.length === 0) {
          message.warning('Vui lòng chọn ít nhất một mục đích khám');
          return;
        }
        visitPurpose = values.visitPurpose.sort().join(',');
      } else if (values.visitPurpose) {
        visitPurpose = values.visitPurpose;
      }

      const patientData = {
        ...values,
        visitPurpose,
        birthDate: values.birthDate ? values.birthDate.toISOString() : null,
        visitStatus: 'waiting', // Always start as waiting
        examinationStatus: 'waiting',
        refractionStatus: 'waiting'
      };

      if (selectedPatient) {
        await updatePatient(selectedPatient.id, patientData);
        message.success('Đã cập nhật thông tin bệnh nhân');
      } else {
        await createPatient(patientData);
        message.success('Đã thêm bệnh nhân mới');
      }

      setModalVisible(false);
      form.resetFields();
      loadPatients(searchQuery);
    } catch (error) {
      message.error('Không thể lưu bệnh nhân');
    }
  };

  const columns = [
    {
      title: 'STT',
      dataIndex: 'queueNumber',
      key: 'queueNumber',
      width: 100,
      render: (text) => <Tag color="red" style={{ fontSize: '14px', fontWeight: 'bold' }}>{text || '-'}</Tag>
    },
    {
      title: 'Mã BN',
      dataIndex: 'code',
      key: 'code',
      width: 150,
      render: (text) => <Tag color="blue">{text}</Tag>
    },
    {
      title: 'Họ tên',
      dataIndex: 'fullName',
      key: 'fullName',
      width: 200
    },
    {
      title: 'SĐT',
      dataIndex: 'phone',
      key: 'phone',
      width: 120
    },
    {
      title: 'Giới tính',
      dataIndex: 'gender',
      key: 'gender',
      width: 100,
      render: (gender) => {
        if (gender === 'male') return 'Nam';
        if (gender === 'female') return 'Nữ';
        return 'Khác';
      }
    },
    {
      title: 'Mục đích',
      dataIndex: 'visitPurpose',
      key: 'visitPurpose',
      width: 150,
      render: (purpose) => {
        if (purpose === 'examination') return <Tag color="green">Khám bệnh</Tag>;
        if (purpose === 'refraction') return <Tag color="blue">Khúc xạ</Tag>;
        if (purpose === 'both' || purpose?.includes(',')) return (
          <>
            <Tag color="green">Khám bệnh</Tag>
            <Tag color="blue">Khúc xạ</Tag>
          </>
        );
        return <Tag>{purpose}</Tag>;
      }
    },
    {
      title: 'Thao tác',
      key: 'actions',
      width: 200,
      fixed: 'right',
      render: (_, record) => (
        <Space size="small">
          {record.queueNumber && record.visitStatus === 'waiting' && (
            <PrintQueueTicketButton
              patient={record}
              onSuccess={() => loadPatients(searchQuery)}
            />
          )}
          <Button
            icon={<EyeOutlined />}
            size="small"
            onClick={() => handleViewDetails(record)}
          />
          <Button
            icon={<EditOutlined />}
            size="small"
            onClick={() => handleEdit(record)}
          />
          <Button
            icon={<DeleteOutlined />}
            size="small"
            danger
            onClick={() => handleDelete(record.id)}
          />
        </Space>
      )
    }
  ];



  return (
    <div>
      <Card
        title={<h2 style={{ margin: 0 }}>Quản lý Tiếp tân</h2>}
        extra={
          <Space>
            <Search
              placeholder="Tìm kiếm bệnh nhân..."
              allowClear
              onSearch={handleSearch}
              onChange={(e) => handleSearch(e.target.value)}
              style={{ width: 300 }}
            />
            <Button
              type="primary"
              icon={<PlusOutlined />}
              onClick={handleAdd}
              size="large"
            >
              Thêm bệnh nhân
            </Button>
          </Space>
        }
      >
        <Space direction="vertical" size="large" style={{ width: '100%' }}>
          {/* Status badges row */}
          <Space size="large">
            <Tag color="orange" style={{ fontSize: '16px', padding: '8px 16px' }}>
              <EyeOutlined /> Chờ khám: {waitingPatients.length}
            </Tag>
            <Tag color="blue" style={{ fontSize: '16px', padding: '8px 16px' }}>
              <EyeOutlined /> Đang khám: {inProgressPatients.length}
            </Tag>
            <Tag color="green" style={{ fontSize: '16px', padding: '8px 16px' }}>
              <EyeOutlined /> Hoàn thành: {completedPatients.length}
            </Tag>
          </Space>

          {/* All patients table */}
          <Table
            columns={columns}
            dataSource={[...waitingPatients, ...inProgressPatients, ...completedPatients]}
            loading={loading}
            rowKey="id"
            scroll={{ x: 1200 }}
            pagination={{
              pageSize: 20,
              showSizeChanger: true,
              showTotal: (total) => `Tổng ${total} bệnh nhân`
            }}
          />
        </Space>
      </Card>

      {/* Add/Edit Modal */}
      <Modal
        title={selectedPatient ? 'Chỉnh sửa bệnh nhân' : 'Thêm bệnh nhân mới'}
        open={modalVisible}
        onCancel={() => {
          setModalVisible(false);
          form.resetFields();
        }}
        footer={null}
        width={700}
      >
        <Form form={form} layout="vertical" onFinish={handleSubmit}>
          <Form.Item
            label="Họ tên"
            name="fullName"
            rules={[{ required: true, message: 'Vui lòng nhập họ tên' }]}
          >
            <Input placeholder="Nhập họ tên bệnh nhân" />
          </Form.Item>

          <Form.Item
            label="Số điện thoại"
            name="phone"
          >
            <Input placeholder="Nhập số điện thoại" />
          </Form.Item>

          <Form.Item
            label="Giới tính"
            name="gender"
            rules={[{ required: true, message: 'Vui lòng chọn giới tính' }]}
          >
            <Select placeholder="Chọn giới tính">
              <Select.Option value="male">Nam</Select.Option>
              <Select.Option value="female">Nữ</Select.Option>
              <Select.Option value="other">Khác</Select.Option>
            </Select>
          </Form.Item>

          <Form.Item
            label="Ngày sinh"
            name="birthDate"
          >
            <DatePicker
              style={{ width: '100%' }}
              format="DD/MM/YYYY"
              placeholder="Chọn ngày sinh"
            />
          </Form.Item>

          <Form.Item
            label="Địa chỉ"
            name="address"
          >
            <Input.TextArea rows={2} placeholder="Nhập địa chỉ" />
          </Form.Item>

          <Form.Item
            label="Mục đích khám"
            name="visitPurpose"
            rules={[{ required: true, message: 'Vui lòng chọn mục đích khám' }]}
          >
            <Checkbox.Group>
              <Checkbox value="examination">Khám bệnh</Checkbox>
              <Checkbox value="refraction">Khúc xạ</Checkbox>
            </Checkbox.Group>
          </Form.Item>

          <Form.Item
            label="Thị lực ban đầu (OD/OS)"
          >
            <Space>
              <Form.Item name="initialVaOd" noStyle>
                <Input placeholder="OD" style={{ width: 100 }} />
              </Form.Item>
              <span>/</span>
              <Form.Item name="initialVaOs" noStyle>
                <Input placeholder="OS" style={{ width: 100 }} />
              </Form.Item>
            </Space>
          </Form.Item>

          <Form.Item
            label="Có đeo kính"
            name="hasGlasses"
            valuePropName="checked"
          >
            <Checkbox>Có</Checkbox>
          </Form.Item>

          <Form.Item
            label="Lý do khám"
            name="visitReason"
          >
            <Input.TextArea rows={2} placeholder="Nhập lý do khám" />
          </Form.Item>

          <Form.Item
            label="Ghi chú"
            name="notes"
          >
            <Input.TextArea rows={2} placeholder="Ghi chú thêm" />
          </Form.Item>

          <Form.Item>
            <Space>
              <Button type="primary" htmlType="submit">
                {selectedPatient ? 'Cập nhật' : 'Thêm mới'}
              </Button>
              <Button onClick={() => {
                setModalVisible(false);
                form.resetFields();
              }}>
                Hủy
              </Button>
            </Space>
          </Form.Item>
        </Form>
      </Modal>

      {/* Details Modal */}
      <Modal
        title="Chi tiết bệnh nhân"
        open={detailsVisible}
        onCancel={() => setDetailsVisible(false)}
        footer={[
          <Button key="close" onClick={() => setDetailsVisible(false)}>
            Đóng
          </Button>
        ]}
        width={600}
      >
        {selectedPatient && (
          <div>
            <p><strong>Mã BN:</strong> {selectedPatient.code}</p>
            <p><strong>Số thứ tự:</strong> {selectedPatient.queueNumber || '-'}</p>
            <p><strong>Họ tên:</strong> {selectedPatient.fullName}</p>
            <p><strong>SĐT:</strong> {selectedPatient.phone || '-'}</p>
            <p><strong>Giới tính:</strong> {selectedPatient.gender === 'male' ? 'Nam' : selectedPatient.gender === 'female' ? 'Nữ' : 'Khác'}</p>
            <p><strong>Ngày sinh:</strong> {selectedPatient.birthDate ? dayjs(selectedPatient.birthDate).format('DD/MM/YYYY') : '-'}</p>
            <p><strong>Địa chỉ:</strong> {selectedPatient.address || '-'}</p>
            <p><strong>Thị lực:</strong> {selectedPatient.initialVaOd || '?'} / {selectedPatient.initialVaOs || '?'}</p>
            <p><strong>Có đeo kính:</strong> {selectedPatient.hasGlasses ? 'Có' : 'Không'}</p>
            <p><strong>Lý do khám:</strong> {selectedPatient.visitReason || '-'}</p>
            <p><strong>Ghi chú:</strong> {selectedPatient.notes || '-'}</p>
          </div>
        )}
      </Modal>
    </div>
  );
}
